import { useState, FormEvent } from 'react';
import { JxInputField, JxSelect, JxSwitch, JxButton, JxAlert } from '@jinx-ui/react';

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function InviteTeamMemberForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const isEmailValid = emailPattern.test(email);
  const emailError = email.length > 0 && !isEmailValid ? 'Введите адрес в формате имя@домен' : undefined;
  const canSubmit = isEmailValid && role.length > 0;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!canSubmit) return;
    setSubmitted(true);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
      {submitted && (
        <JxAlert intent="success" title="Приглашение отправлено" onClick={undefined}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 'var(--jx-r-sm)' }}>
            <span>Мы отправили приглашение на {email}.</span>
            <JxButton
              variant="ghost"
              size="sm"
              iconOnly
              aria-label="Закрыть сообщение"
              onClick={() => setSubmitted(false)}
            >
              ×
            </JxButton>
          </div>
        </JxAlert>
      )}

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@company.com"
          helperText="Приглашение придёт на этот адрес"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          errorText={emailError}
        />

        <JxSelect
          label="Роль"
          placeholder="Выберите роль"
          options={[
            { value: 'member', label: 'Участник' },
            { value: 'admin', label: 'Администратор' },
            { value: 'viewer', label: 'Наблюдатель' },
          ]}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление на почту"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <div>
          <JxButton type="submit" variant="primary" disabled={!canSubmit}>
            Отправить приглашение
          </JxButton>
        </div>
      </form>
    </div>
  );
}

